function Welcome({ name, onHello }) {
  return <button className="rounded-lg px-4 py-2" onClick={onHello}>{name}</button>
}

function Results({ count }) {
  return count > 0 ? <p>Найдено: {count}</p> : <p>Ничего не найдено</p>
}

import { Fragment } from "react"

function Glossary({ terms }) {
  return <dl>{terms.map(term => (
    <Fragment key={term.id}><dt>{term.name}</dt><dd>{term.description}</dd></Fragment>
  ))}</dl>
}

function EmptyState({ title, children }) {
  return <section><h2>{title}</h2>{children}</section>
}
// Контейнер отвечает за рамку представления, вызывающий код - за действия.
